import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import CommandPaletteTitle from "./CommandPaletteTitle.js";

describe("CommandPaletteTitle", () => {
  it("renders its children in a span with both its classes", () => {
    render(
      <CommandPaletteTitle className="title">
        Layout switcher
      </CommandPaletteTitle>,
    );
    const title = screen.getByText("Layout switcher");
    expect(title.tagName).toBe("SPAN");
    expect(title.className).toBe("ds command-palette-title title");
  });

  it("drops the href a row hands it, so it is never a link", () => {
    const { container } = render(
      <CommandPaletteTitle href="/things/ds%3ALayout">
        Layout
      </CommandPaletteTitle>,
    );
    expect(container.querySelector("a")).toBeNull();
    expect(container.querySelector("[href]")).toBeNull();
    expect(screen.queryByRole("link")).toBeNull();
  });

  it("passes through additional props", () => {
    render(
      <CommandPaletteTitle aria-current="page" data-testid="test-component">
        Layout
      </CommandPaletteTitle>,
    );
    expect(screen.getByTestId("test-component")).toHaveAttribute(
      "aria-current",
      "page",
    );
  });
});
